function runtimeView(px,py,pz,tx,ty,tz,fov)
 if RUNTIMECAM==nil then RUNTIMECAM=createCamera('RuntimeFlatbedReview',math.rad(38),.05,500);link(getRootNode(),RUNTIMECAM) end
 setTranslation(RUNTIMECAM,px,py,pz);setDirection(RUNTIMECAM,px-tx,py-ty,pz-tz,0,1,0);setFovY(RUNTIMECAM,math.rad(fov or 38));setCamera(RUNTIMECAM);clearSelection()
end
local function pose_additionalForks(t)
setTranslation(N["flatbedStakeLeft1"],(-1.23+(0.0)*t),(1.62+(0.0)*t),(-5.1+(1.1299999999999994)*t))
setTranslation(N["flatbedStakeLeft3"],(-1.23+(0.0)*t),(1.62+(0.0)*t),(-2.56+(1.1300000000000001)*t))
setTranslation(N["flatbedStakeLeft5"],(-1.23+(0.0)*t),(1.62+(0.0)*t),(-0.02+(1.1300000000000001)*t))
setTranslation(N["flatbedStakeRight1"],(1.23+(0.0)*t),(1.62+(0.0)*t),(-5.1+(1.1299999999999994)*t))
setTranslation(N["flatbedStakeRight3"],(1.23+(0.0)*t),(1.62+(0.0)*t),(-2.56+(1.1300000000000001)*t))
setTranslation(N["flatbedStakeRight5"],(1.23+(0.0)*t),(1.62+(0.0)*t),(-0.02+(1.1300000000000001)*t))
end
local function pose_flatbedBoards(t)
setRotation(N["flatbedBoardLeft1"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(180.0)*t)))
setRotation(N["flatbedBoardLeft2"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(180.0)*t)))
setRotation(N["flatbedBoardLeft3"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(180.0)*t)))
setRotation(N["flatbedBoardRight1"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(-180.0)*t)))
setRotation(N["flatbedBoardRight2"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(-180.0)*t)))
setRotation(N["flatbedBoardRight3"],math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(-180.0)*t)))
setRotation(N["flatbedTailgate"],math.rad((0.0+(-180.0)*t)),math.rad((0.0+(0.0)*t)),math.rad((0.0+(0.0)*t)))
end
function runtimePose(stakes,t,tail)
 setVisibility(N.OPTION_STAKES,stakes);setVisibility(N.OPTION_BOARDS,not stakes)
 pose_flatbedBoards(stakes and 0 or t);pose_additionalForks(stakes and t or 0);pose_flatbedTailgate(tail or 0)
end
